/* ================================================================= */
/* 01. GLOBAL GEOMETRY & LAYOUT                                      */
/* ----------------------------------------------------------------- */
/* Design tokens every other section reads: the 2px thickness token, */
/* zeroed radii, removed shadows, button physics, fonts, callout hue */
/* and the header pattern. Change a token here, not a value below.   */
/* See also: 24 (patterns), 32 (presets override the raw palette)    */
/* ================================================================= */

body.obsidian-app {
  /* === THICKNESS === */
  --aubade-thickness: 2px;

  /* === BORDER WIDTHS === */
  --border-width: var(--aubade-thickness);
  --callout-border-width: var(--aubade-thickness);
  --input-border-width: var(--aubade-thickness);
  --nav-guide-border-width: var(--aubade-thickness);
  --tag-border-width: var(--aubade-thickness);
  --divider-width: var(--aubade-thickness);
  --tab-outline-width: var(--aubade-thickness);

  /* === RADIUS (all zero) === */
  --menu-radius: 0;
  --radius-s: 0;
  --radius-m: 0;
  --radius-l: 0;
  --radius-xl: 0;
  --tab-radius: 0;
  --tab-radius-active: 0;
  --tab-curve: 0;
  --tag-radius: 0;
  --button-radius: 0;
  --input-radius: 0;
  --modal-radius: 0;
  --checkbox-radius: 0;
  --toggle-thumb-radius: 0;
  --callout-radius: 0;
  --status-bar-radius: 0;
  --list-bullet-radius: 0;
  --table-selection-border-radius: 0;
  --code-radius: 0;
  --scrollbar-radius: 0;

  /* === SHADOWS (all removed) === */
  --input-shadow: none;
  --input-shadow-hover: none;
  --shadow-s: none;

  /* === BUTTON PHYSICS === */
  --button-shadow-offset: 4px;
  --button-shadow-hover-offset: 6px;
  --button-lift: -2px;
  --button-press: 2px;
  --button-transition: transform 0.1s ease, box-shadow 0.1s ease;

  /* === TYPOGRAPHY === */
  --font-interface-override: var(--user-font-ui, 'Space Mono', monospace);
  --font-interface: var(--font-interface-override);
  --font-default: var(--font-interface-override);
  --font-ui: var(--font-interface-override);
  --font-text-override: var(--user-font-body, 'iA Writer Quattro S', sans-serif);
  --font-text: var(--font-text-override);
  --font-text-theme: var(--font-text-override);
  --font-monospace-override: var(--user-font-mono, 'Space Mono', monospace);
  --font-monospace: var(--font-monospace-override);

  /* === LAYOUT === */
  --line-height-custom: 1.5;
  --inline-title-size: 3em;
  --text-align-mode: left;
  --editor-width: 700px;
  --file-line-width: var(--editor-width);
  --icon-size: 20px;
  --dashboard-col-width: 300px;
  --dashboard-gap: 8px;
  --inline-title-alignment: center;

  /* === CALLOUT HUES === */
  /* One place to retune callout semantics. The hues stay fixed; the strength
     they are applied at is always mixed against the current background, so
     every colour preset gets a tint that suits its own contrast. */
  --aubade-callout-blue: rgb(8, 109, 221);
  --aubade-callout-teal: rgb(0, 191, 188);
  --aubade-callout-green: rgb(8, 185, 78);
  --aubade-callout-amber: rgb(236, 163, 0);
  --aubade-callout-red: rgb(233, 49, 71);
  --aubade-callout-purple: rgb(120, 82, 238);
  --aubade-callout-grey: rgb(158, 158, 158);
  --aubade-callout-tint: 15%;
  /* Share of background in the title plate fill. The plate alone carries the
     callout hue, so this is the one knob that decides how strongly a callout's
     type reads. 85% made the hue vanish on saturated presets. */
  --aubade-callout-plate: 72%;

  /* === HEADER PATTERNS === */
  /* Patterns draw with --aubade-pattern-color, which defaults to the divider.
     Override it alongside a --top-pattern-img declaration (e.g. on a preset)
     to retint every pattern at once; it has no effect set on a descendant,
     because the var() inside --top-pattern-img resolves where that property
     is declared. */
  --aubade-pattern-color: var(--aubade-divider-color);
  --top-pattern-img: conic-gradient(var(--aubade-pattern-color) 90deg,
      transparent 90deg 180deg,
      var(--aubade-pattern-color) 180deg 270deg,
      transparent 270deg);
  --top-pattern-size: 4px 4px;
  --top-pattern-pos: 0 0;
}

/* Inline Title */
body.obsidian-app .inline-title:not(.popover *),
body.obsidian-app .markdown-source-view .cm-content .inline-title:not(.popover *) {
  font-synthesis: none;
  font-size: var(--inline-title-size);
  text-align: var(--inline-title-alignment);
  font-family: var(--font-interface-override);
  font-weight: 700;
}

/* TIMELINE */
/*
  Custom properties — tweak these to adjust the layout globally.
  --tl-date-width   : width of the left date column
  --tl-row-gap      : vertical spacing between timeline entries
  --tl-dot-size     : diameter of the accent dot
  --tl-dot-color    : accent dot colour (defaults to the divider colour)
*/
html body.obsidian-app .markdown-preview-view.custom-timeline {
  --tl-date-width: 200px;
  --tl-row-gap: 2.5rem;
  --tl-dot-size: 1.2rem;
  --tl-dot-color: var(--aubade-divider-color);
}

/* ================================================================= */
/* 02. DARK MODE COLOURS                                             */
/* ----------------------------------------------------------------- */
/* Raw palette -> Obsidian variables. Presets in 32 override the raw */
/* values only, so every mapping below survives a preset change.     */
/* See also: 3, 32                                                   */
/* ================================================================= */

html body.obsidian-app.theme-dark {
  /* === RAW COLOR PALETTE === */
  --raw-bg-primary: #303841;
  --raw-bg-secondary: #222831;
  --raw-text-primary: var(--body-font-color-dark, #b3b3b3);
  --raw-text-secondary: var(--ui-font-color-dark, #b3b3b3);
  --raw-border: #4A5869;
  --raw-interactive: #CCCCCC;
  --raw-hover-bg: #DDE6ED;
  --raw-selection-bg: #1a4a5c;
  --raw-highlight-bg: #5e2b2b;
  --raw-code-bg: #1A1D21;
  --raw-inverse: #DDE6ED;

  /* === BACKGROUNDS === */
  --background-primary: var(--raw-bg-primary);
  --background-primary-alt: var(--raw-bg-primary);
  --background-secondary: var(--raw-bg-secondary);
  --background-secondary-alt: var(--raw-bg-secondary);
  --background-modifier-border: var(--raw-border);
  --background-modifier-form-field: var(--raw-bg-secondary);

  /* === TEXT === */
  --text-normal: var(--raw-text-primary);
  --text-muted: var(--raw-text-secondary);
  --text-faint: var(--raw-text-secondary);
  --text-accent: var(--raw-interactive);
  /* Must be readable on --interactive-accent (--raw-border), not on the page. */
  --text-on-accent: #FFFFFF;
  /* The hover accent (--interactive-accent-hover) is a different, usually
     lighter surface than --interactive-accent, so it needs its own text
     colour - see the .mod-cta:hover rules. */
  --aubade-on-accent-hover: #FFFFFF;  /* 14.83:1 on #222831 */
  --color-dot: var(--raw-text-primary);
  --color-text-day: var(--raw-text-primary);
  --color-arrow: var(--raw-text-primary);
  --color-button: var(--raw-text-primary);
  --color-text-heading: var(--raw-text-primary);
  --color-text-title: var(--raw-text-primary);
  --color-text-today: var(--raw-text-primary);
  --color-text-weeknum: var(--raw-text-primary);
  --color-base-100: var(--raw-text-primary);
  --heading-formatting: var(--raw-text-primary);
  --checklist-done-color: var(--raw-text-primary);
  --flair-color: var(--raw-text-primary);
  --footnote-id-color: var(--raw-text-primary);
  --footnote-id-color-no-occurrences: var(--raw-text-primary);
  --input-date-separator: var(--raw-text-primary);
  --input-placeholder-color: var(--raw-text-primary);
  --caret-color: var(--raw-text-primary);

  /* === INTERACTIVE STATES === */
  --background-modifier-hover: #38424e;
  --background-modifier-active-hover: var(--raw-hover-bg);
  --interactive-hover: color-mix(in srgb, var(--background-secondary), var(--raw-hover-bg) 20%);
  --interactive-accent: var(--raw-border);
  --interactive-accent-hover: #222831;
  --interactive-normal: var(--background-primary);

  /* === SELECTION & HIGHLIGHT === */
  --text-selection: var(--raw-selection-bg);
  --text-selection-color: var(--text-normal);
  --text-highlight-bg: var(--raw-highlight-bg);

  /* === BORDERS & DIVIDERS === */
  --aubade-divider-color: var(--raw-border);
  --aubade-shadow-color: var(--raw-border);
  --tab-outline-color: var(--raw-border);
  --checkbox-border-color: var(--raw-border);
  --checkbox-border-color-hover: var(--raw-border);

  /* === CODE === */
  --code-background: var(--raw-code-bg);

  /* === ICONS === */
  --icon-color: var(--raw-text-primary);
  --icon-color-focused: var(--raw-text-primary);
  --icon-color-hover: var(--text-normal);
  --collapse-icon-color: var(--raw-text-primary);
  --search-clear-button-color: var(--raw-text-primary);
  --search-icon-color: var(--raw-text-primary);

  /* === NAV === */
  --nav-collapse-icon-color: var(--raw-text-primary);
  --nav-collapse-icon-color-collapsed: var(--raw-text-primary);
  --nav-heading-color: var(--raw-text-primary);
  --nav-heading-color-collapsed: var(--raw-text-primary);
  --nav-heading-color-collapsed-hover: var(--raw-text-primary);
  --nav-heading-color-hover: var(--raw-text-primary);
  --nav-item-color: var(--raw-text-primary);
  --nav-item-color-active: var(--raw-text-primary);
  --nav-item-color-hover: var(--raw-text-primary);
  --nav-item-color-selected: var(--raw-text-primary);
  --nav-tag-color: var(--raw-text-primary);
  --nav-tag-color-active: var(--raw-text-primary);
  --nav-tag-color-hover: var(--raw-text-primary);

  /* === TABS === */
  --tab-hover-bg-ui: var(--raw-hover-bg);
  --tab-hover-text-ui: #000000;
  --tab-text-color: var(--raw-text-primary);
  --tab-text-color-active: var(--raw-text-primary);
  --tab-text-color-focused: var(--raw-text-primary);
  --tab-text-color-focused-active: var(--raw-text-primary);
  --tab-text-color-focused-active-current: var(--raw-text-primary);
  --titlebar-text-color: var(--raw-text-primary);
  --titlebar-text-color-focused: var(--raw-text-primary);

  /* === TABLES & BASES === */
  --bases-group-heading-property-color: var(--raw-text-primary);
  --bases-table-header-color: var(--raw-text-primary);
  --table-header-color: var(--raw-text-primary);
  --table-drag-handle-color: var(--raw-text-primary);
  --table-drag-handle-color-active: var(--raw-text-primary);

  /* === METADATA === */
  --metadata-input-text-color: var(--raw-text-primary);
  --metadata-label-text-color: var(--raw-text-primary);
  --metadata-label-text-color-hover: var(--raw-text-primary);

  /* === BUTTONS & TAGS === */
  --tag-border-color-hover: color-mix(in srgb, var(--raw-text-secondary), white 40%);
  --pill-color: var(--raw-text-primary);
  --pill-color-hover: var(--raw-text-primary);
  --pill-color-remove: var(--raw-text-secondary);

  /* === MOBILE === */
  --mobile-navbar-bg: var(--raw-bg-primary);
  --mobile-active-bg: var(--raw-bg-secondary);
  --metadata-bg-mobile-dark: #1e2227;

  /* === MISC === */
  --canvas-card-label-color: var(--raw-text-primary);
  --graph-node: var(--raw-text-primary);
  --graph-node-unresolved: var(--raw-text-primary);
  --graph-text: var(--raw-text-primary);
  --list-marker-color: var(--raw-text-primary);
  --list-marker-color-hover: var(--raw-text-primary);
  --setting-group-heading-color: var(--raw-text-primary);
  --status-bar-text-color: var(--raw-text-primary);
  --vault-profile-color: var(--raw-text-primary);
  --vault-profile-color-hover: var(--raw-text-primary);

  /* === ACCENT === */
  --color-accent: var(--raw-interactive);
  --accent-h: 0;
  --accent-s: 0%;
  --accent-l: 80%;

  /* Native variables mapped to the Style Settings pickers, falling back to the
     UI colour when the user has not chosen one. Do not re-declare the
     --link-*-custom variables here: this block outranks the `body` rule Style
     Settings writes, which would make the pickers inert. */
  --link-color: var(--link-color-dark-custom, var(--raw-text-secondary));
  --link-external-color: var(--link-ext-color-dark-custom, var(--raw-text-secondary));

  /* Hover states mapped to Body text colour */
  --link-color-hover: var(--text-normal);
  --link-external-color-hover: var(--text-normal);

  /* === TOGGLE ON COLOR === */
  --toggle-on-color: #25efa5;
}


