  --nav-heading-color: var(--raw-text-primary);
  --nav-heading-color-collapsed: var(--raw-text-primary);
  --nav-heading-color-collapsed-hover: var(--raw-text-primary);
  --nav-heading-color-hover: var(--raw-text-primary);
  --nav-item-color: var(--raw-text-primary);
  --nav-item-color-active: var(--raw-text-primary);
  --nav-item-color-hover: var(--raw-text-primary);
  --nav-item-color-selected: var(--raw-text-primary);
  --nav-tag-color: var(--raw-text-primary);
  --nav-tag-color-active: var(--raw-text-primary);
  --nav-tag-color-hover: var(--raw-text-primary);

  /* === TABS === */
  --tab-hover-bg-ui: var(--raw-hover-bg);
  --tab-hover-text-ui: var(--raw-text-primary);
  --tab-text-color: var(--raw-text-primary);
  --tab-text-color-active: var(--raw-text-primary);
  --tab-text-color-focused: var(--raw-text-primary);
  --tab-text-color-focused-active: var(--raw-text-primary);
  --tab-text-color-focused-active-current: var(--raw-text-primary);
  --titlebar-text-color: var(--raw-text-primary);
  --titlebar-text-color-focused: var(--raw-text-primary);

  /* === TABLES & BASES === */
  --bases-group-heading-property-color: var(--raw-text-primary);
  --bases-table-header-color: var(--raw-text-primary);
  --table-header-color: var(--raw-text-primary);
  --table-drag-handle-color: var(--raw-text-primary);
  --table-drag-handle-color-active: var(--raw-text-primary);

  /* === METADATA === */
  --metadata-input-text-color: var(--raw-text-primary);
  --metadata-label-text-color: var(--raw-text-primary);
  --metadata-label-text-color-hover: var(--raw-text-primary);

  /* === BUTTONS & TAGS === */
  --tag-border-color-hover: var(--raw-interactive);
  --pill-color: var(--raw-text-primary);
  --pill-color-hover: var(--raw-text-primary);
  --pill-color-remove: var(--raw-text-secondary);

  /* === MOBILE === */
  --mobile-navbar-bg: var(--raw-bg-primary);
  --mobile-active-bg: var(--raw-bg-secondary);
  --metadata-bg-mobile-light: #c5c4a5;

  /* === MISC === */
  --canvas-card-label-color: var(--raw-text-primary);
  --graph-node: var(--raw-text-primary);
  --graph-node-unresolved: var(--raw-text-primary);
  --graph-text: var(--raw-text-primary);
  --list-marker-color: var(--raw-text-primary);
  --list-marker-color-hover: var(--raw-text-primary);
  --setting-group-heading-color: var(--raw-text-primary);
  --status-bar-text-color: var(--raw-text-primary);
  --vault-profile-color: var(--raw-text-primary);
  --vault-profile-color-hover: var(--raw-text-primary);

  /* === ACCENT === */
  --color-accent: var(--raw-interactive);
  --accent-h: 0;
  --accent-s: 0%;
  --accent-l: 0%;

  /* See the dark-mode block: the --link-*-custom variables are deliberately not
     re-declared here so the Style Settings pickers keep working. */
  --link-color: var(--link-color-light-custom, var(--raw-text-secondary));
  --link-external-color: var(--link-ext-color-light-custom, var(--raw-text-secondary));

  /* Hover states follow the Body font colour */
  --link-color-hover: var(--text-normal);
  --link-external-color-hover: var(--text-normal);

  /* === TOGGLE ON COLOR === */
  --toggle-on-color: #ff7700;
}

/* ================================================================= */
/* 04. TEXT SELECTION & HIGHLIGHTING                                 */
/* ----------------------------------------------------------------- */
/* Selection colour in both the editor and rendered views.           */
/* ================================================================= */

html body.obsidian-app ::selection {
  background-color: color-mix(in srgb, var(--text-selection), transparent 30%);
  color: var(--text-normal);
}

html body.obsidian-app .cm-selectionBackground,
html body.obsidian-app .cm-line::selection,
html body.obsidian-app .cm-content::selection,
html body.obsidian-app .cm-scroller ::selection {
  background-color: color-mix(in srgb, var(--text-selection), transparent 30%);
  color: var(--text-normal);
}

/* ================================================================= */
/* 05. LISTS & MARKERS                                               */
/* ----------------------------------------------------------------- */
/* Bullet and ordered-list markers, reading and editing views.       */
/* ================================================================= */

html body.obsidian-app .markdown-preview-view ul>li,
html body.obsidian-app .markdown-preview-view ol>li,
html body.obsidian-app .markdown-preview-view ul>li>p,
html body.obsidian-app .markdown-preview-view ol>li>p,
html body.obsidian-app .cm-s-obsidian .HyperMD-list-line,
html body.obsidian-app .cm-line {
  color: var(--text-normal);
}

html body.obsidian-app .markdown-preview-view ul>li::marker,
html body.obsidian-app .markdown-preview-view ol>li::marker,
html body.obsidian-app .markdown-preview-view blockquote ul>li::marker,
html body.obsidian-app .markdown-preview-view blockquote ol>li::marker,
html body.obsidian-app .cm-formatting-list,
html body.obsidian-app .cm-formatting-list-ul,
html body.obsidian-app .cm-formatting-list-ol,
html body.obsidian-app .cm-s-obsidian .cm-quote .cm-formatting-list {
  color: var(--text-accent);
  font-weight: bold;
  opacity: 1;
}

html body.obsidian-app.theme-light .cm-formatting-list-ol {
  color: var(--text-accent);
}

/* ================================================================= */
/* 06. WORKSPACE TABS                                                */
/* ----------------------------------------------------------------- */
/* Root and sidebar tab headers: hover, active, inactive, icons.     */
/* See also: 7, 25 (sidebar tabs), 24 (tab bar pattern)              */
/* ================================================================= */

html body.obsidian-app .workspace-tab-header-container {
  padding-bottom: 0;
  margin-bottom: 0;
}

html body.obsidian-app div.workspace-tab-header-inner::after {
  display: none;
}

/* -- Hover states ------------------------------------------------- */
@media (hover: hover) {
  html body.obsidian-app .mod-root .workspace-tab-header:not(.is-active):not(.workspace-tab-header-new-tab):not(.workspace-tab-header-tab-list):hover .workspace-tab-header-inner {
    background-color: var(--background-modifier-hover);
    color: var(--text-normal);
  }

  html body.obsidian-app .mod-left-split .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner,
  html body.obsidian-app .mod-right-split .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner,
  html body.obsidian-app .workspace-tab-header-new-tab:hover .workspace-tab-header-inner,
  html body.obsidian-app .workspace-tab-header-tab-list:hover .workspace-tab-header-inner {
    background-color: color-mix(in srgb, var(--tab-hover-bg-ui), transparent 50%);
    color: var(--tab-hover-text-ui);
  }

  html body.obsidian-app .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner-title {
    color: var(--text-normal);
  }
}

/* -- Active tabs -------------------------------------------------- */
html body.obsidian-app .mod-root .workspace-tab-header.is-active .workspace-tab-header-inner {
  color: var(--text-normal);
  background-color: var(--background-primary);
  border: none;
  z-index: 2;
  position: relative;
  border-radius: 0;
  padding: 0 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  height: 100%;
}

html body.obsidian-app.is-mobile :is(.mod-left-split, .mod-right-split) .workspace-tab-header.is-active .workspace-tab-header-inner {
  border-radius: 0;
}

html body.obsidian-app:not(.is-mobile) :is(.mod-left-split, .mod-right-split) .workspace-tab-header.is-active .workspace-tab-header-inner {
  background-color: transparent;
  border-radius: 0;
}

html body.obsidian-app .workspace-tab-header.is-active .workspace-tab-header-inner-icon {
  margin: 0 auto;
  display: flex;
  align-items: center;
}

html body.obsidian-app .mod-root .workspace-tab-header.is-active,
html body.obsidian-app .mod-left-split .workspace-tab-header.is-active,
html body.obsidian-app .mod-right-split .workspace-tab-header.is-active {
  background-color: var(--background-primary);
  padding: 0;
  border: var(--border-width) solid var(--aubade-divider-color) !important;
  margin-top: 0;
  margin-right: var(--aubade-thickness);
  margin-bottom: calc(var(--aubade-thickness) * -1);
  box-shadow: none;
  outline: none;
  z-index: 100;
}

/* -- Inactive tabs ------------------------------------------------ */
html body.obsidian-app .workspace-tab-header:not(.is-active) {
  background-color: var(--background-secondary);
  border: var(--border-width) solid var(--aubade-divider-color);
  margin: 4px var(--aubade-thickness) 0 0;
  padding: 0 !important;
}

html body.obsidian-app .mod-root .workspace-tab-header:not(.is-active) .workspace-tab-header-inner {
  background: transparent;
  color: var(--text-normal);
  padding: 0 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  height: 100%;
}

html body.obsidian-app .mod-left-split .workspace-tab-header:not(.is-active),
html body.obsidian-app .mod-right-split .workspace-tab-header:not(.is-active) {
  background-color: var(--background-secondary);
  opacity: 1;
}


/* -- View header title -------------------------------------------- */
html body.obsidian-app .workspace-leaf.mod-active .view-header-title {
  color: var(--text-accent);
}

html body.obsidian-app.theme-light .workspace-leaf.mod-active .view-header-title {
  font-weight: bold;
}

html body.obsidian-app .workspace-leaf:not(.mod-active) .view-header-title {
  color: var(--text-muted);
}

/* Forces inactive tab icons to text-normal, preventing file-type specific colors */
html body.obsidian-app .workspace-tab-header:not(.is-active) .workspace-tab-header-inner-icon svg {
  color: var(--text-normal);
  stroke: var(--text-normal);
}

/* Forces all tab icons (File icons, Pins, Audio, etc.) to follow the UI Font Colour */
html body.obsidian-app :is(.workspace-tab-header-inner-icon, .workspace-tab-header-status-icon) svg {
  color: var(--raw-text-secondary);
  stroke: var(--raw-text-secondary);
  fill: none;
  opacity: 1;
}

/* Hover state: icons shift to Body text colour for visual feedback */
@media (hover: hover) {
  html body.obsidian-app :is(.workspace-tab-header-inner-icon, .workspace-tab-header-status-icon):hover svg {
    color: var(--text-normal);
    stroke: var(--text-normal);
  }
}

/* ================================================================= */
/* 07. HEADER ICON ACTIVE STATES                                     */
/* ----------------------------------------------------------------- */
/* Suppresses the press animation on tab-bar chrome buttons.         */
/* See also: 6, 27                                                   */
/* ================================================================= */

html body.obsidian-app .sidebar-toggle-button:active,
html body.obsidian-app .workspace-tab-header-new-tab:active,
html body.obsidian-app .workspace-tab-header-tab-list:active {
  transform: none;
  box-shadow: none;
}

/* ================================================================= */
/* 08. HOVER & INTERACTIVE STATES                                    */
/* ----------------------------------------------------------------- */
/* Shared hover/selected treatment for ribbon, status bar, menus,    */
/* suggestions and the file tree. Desktop hover is gated behind      */
/* @media (hover: hover) so touch devices never stick in hover.      */
/* See also: 20 (mobile equivalents)                                 */
/* ================================================================= */

@media (hover: hover) {

  html body.obsidian-app :is(.side-dock-ribbon-action,
    .status-bar-item,
    .clickable-icon,
    .menu-item,
    .suggestion-item,
    .tag-pane-tag,
    .workspace-drawer-vault-switcher):hover {
    background-color: color-mix(in srgb, var(--background-modifier-hover), transparent 50%);
    opacity: 1;
    border-radius: 0;
  }

  html body.obsidian-app :is(.side-dock-ribbon-action, .status-bar-item, .menu-item):hover :is(svg, .svg-icon, .menu-item-title) {
    color: var(--text-muted);
    stroke: var(--text-muted);
    fill: none;
  }

  html body.obsidian-app :is(.nav-file-title, .nav-folder-title, .tree-item-self):hover :is(.nav-file-title-content, .nav-folder-title-content) {
    color: var(--text-normal);
  }

  /* === FILE EXPLORER HOVER === */
  html body.obsidian-app .nav-file-title:hover,
  html body.obsidian-app .nav-folder-title:hover,
  html body.obsidian-app :is(.nav-file-title, .nav-folder-title, .tree-item-self):hover {
    background-color: color-mix(in srgb, var(--background-modifier-hover), transparent 50%);
    opacity: 1;
    border-radius: 0;
  }
}

html body.obsidian-app :is(.menu-item, .suggestion-item, .vertical-tab-nav-item):is(.is-selected, .is-active, :active) {
  background-color: var(--background-modifier-hover);
  opacity: 1;
  border-radius: 0;
  box-shadow: none;
}

html body.obsidian-app.is-mobile .workspace-drawer-tab-options-list .workspace-tab-header:active,
html body.obsidian-app.is-mobile .workspace-drawer-tab-options-list .workspace-tab-header.is-active {
  background-color: var(--mobile-active-bg);
  border: var(--border-width) solid var(--aubade-divider-color);
  padding: 0;
}

html body.obsidian-app.is-mobile .workspace-drawer-tab-options-list .workspace-tab-header.is-active .workspace-tab-header-inner {
  padding: 8px;
  background-color: var(--mobile-active-bg) !important;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: flex-start;
  align-items: center;
}

/* Restores inactive drawer tab layout */
html body.obsidian-app.is-mobile .workspace-drawer-tab-options-list .workspace-tab-header:not(.is-active) .workspace-tab-header-inner {
  padding: 8px;
  display: flex;
  justify-content: flex-start;
  align-items: center;
  background: transparent;
  width: 100%;
  height: 100%;
}

/* -- Chevrons ----------------------------------------------------- */
html body.obsidian-app .svg-icon.right-triangle {
  color: var(--text-normal);
  stroke: var(--text-normal);
}

/* -- Active states ------------------------------------------------ */
html body.obsidian-app .clickable-icon.is-active,
html body.obsidian-app .side-dock-ribbon-action.is-active,
html body.obsidian-app .nav-action-button.is-active,
html body.obsidian-app .mod-left-split .workspace-tab-header.is-active .workspace-tab-header-inner,
html body.obsidian-app .workspace-drawer .workspace-tab-header.is-active .workspace-tab-header-inner {
  box-shadow: none;
  border-radius: 0;
  color: var(--text-accent);
  stroke: var(--text-accent);
}

/* Nav file/folder selection border + Shadow/Focus Reset */
html body.obsidian-app :is(.nav-file-title, .nav-folder-title).is-active.has-focus {
  outline: var(--aubade-thickness) solid var(--aubade-divider-color);
  outline-offset: calc(var(--aubade-thickness) * -1);
  background-color: var(--background-primary);
  /* Kills the native grey focus ring and shadows */
  box-shadow: none;
}

/* Ensures the native browser focus doesn't create a secondary grey border */
html body.obsidian-app :is(.nav-file-title, .nav-folder-title):focus {
  outline: none;
  box-shadow: none;
}

/* Dims the drawer title and icon when not collapsed  */
/* Targets the icon (and the SVG inside it) and the title */
html body.obsidian-app.is-mobile .workspace-drawer-tab-options:not(.is-collapsed) .workspace-drawer-tab-select :is(.workspace-tab-header-inner-icon, .workspace-tab-header-inner-icon svg, .workspace-tab-header-inner-title) {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

/* Restores visibility when collapsed */
html body.obsidian-app.is-mobile .workspace-drawer-tab-options.is-collapsed .workspace-drawer-tab-select :is(.workspace-tab-header-inner-icon, .workspace-tab-header-inner-icon svg, .workspace-tab-header-inner-title) {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

/* -- Tab bar icon hover (desktop) --------------------------------- */

/* Reserves outline space at rest so icons don't shift when border appears on hover */
html body.obsidian-app:not(.is-mobile) .workspace-tab-header-container .clickable-icon,
html body.obsidian-app:not(.is-mobile) .sidebar-toggle-button.mod-left .clickable-icon,
html body.obsidian-app:not(.is-mobile) .sidebar-toggle-button.mod-right .clickable-icon {
  outline: var(--border-width) solid transparent;
}

@media (hover: hover) {

  html body.obsidian-app:not(.is-mobile) .workspace-tab-header-container .clickable-icon:hover,
  html body.obsidian-app:not(.is-mobile) .workspace-tab-header-new-tab:hover>.clickable-icon,
  html body.obsidian-app:not(.is-mobile) .workspace-tab-header-tab-list:hover>.clickable-icon,
  html body.obsidian-app:not(.is-mobile) .sidebar-toggle-button.mod-left .clickable-icon:hover,
  html body.obsidian-app:not(.is-mobile) .sidebar-toggle-button.mod-right .clickable-icon:hover {
    outline-color: var(--aubade-divider-color);
  }
}

/* ================================================================= */
/* 09. SIDEBAR TOGGLE BUTTON                                         */
/* ----------------------------------------------------------------- */
/* Left and right sidebar toggles and the search-settings icon.      */
/* See also: 20, 27                                                  */
/* ================================================================= */

@media (hover: hover) {

  html body.obsidian-app .sidebar-toggle-button:hover svg,
  html body.obsidian-app .workspace-tab-header-new-tab:hover svg,
  html body.obsidian-app .workspace-tab-header-tab-list:hover svg {
    stroke: var(--text-normal);
    color: var(--text-normal);
    opacity: 1;
  }

  html body.obsidian-app .sidebar-toggle-button:hover .sidebar-toggle-icon-inner {
    fill: var(--text-normal);
    opacity: 1;
  }

  html body.obsidian-app .workspace-tab-header-new-tab:hover,
  html body.obsidian-app .workspace-tab-header-tab-list:hover {
    background-color: transparent;
    box-shadow: none;
  }
}

html body.obsidian-app.is-mobile .sidebar-toggle-button button:hover,
html body.obsidian-app.is-mobile .view-action.sidebar-toggle-button:hover {
  background-color: var(--background-primary);
  box-shadow: var(--button-shadow-offset) var(--button-shadow-offset) 0 0 var(--aubade-divider-color);
  transform: none;
  color: var(--text-normal);
  opacity: 1;
}

/* Search-settings toggle. Targeted structurally: an aria-label match only
   works in the language the label was copied from. */
html body.obsidian-app .search-row > .clickable-icon:not(.input-right-decorator):not(.is-active):hover,
html body.obsidian-app .search-row > .clickable-icon:not(.input-right-decorator):not(.is-active):hover svg {
  color: var(--text-muted);
  stroke: var(--text-muted);
}

/* ================================================================= */
/* 10. SETTINGS ICON                                                 */
/* ----------------------------------------------------------------- */
/* Custom masked settings glyph and the vault-action buttons.        */
/* ================================================================= */

html body.obsidian-app .svg-icon.lucide-settings,
html body.obsidian-app .workspace-drawer-header-icon.mod-settings>.svg-icon {
  fill: none;
  stroke: none;
  stroke-width: 0;
  border: none;
  box-shadow: none;
  --icon-settings-svg: url("data:image/svg+xml,%3Csvg%20viewBox%3D%22-70%20-70%20652%20652%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cpath%20d%3D%22M175.576%20430.027C237.876%20303.719%20177.358%20246.189%20138.563%20220.91M199.593%20302.823C260.138%20288.119%20319.001%20288.974%20360.236%20377.756M263.64%20296.151C204.786%20148.805%20301.519%20142.938%20277.563%2064.4366M360.236%20377.756C361.585%20375.292%20363.038%20372.884%20364.603%20370.549C381.579%20345.235%20393.569%20325.505%20399.638%20315.229C402.426%20310.512%20401.92%20304.599%20398.621%20300.226C390.022%20288.832%20373.568%20265.675%20364.603%20244.234C355.387%20222.192%20354.012%20187.968%20353.933%20171.298C353.903%20164.963%20351.895%20158.774%20347.977%20153.794L278.719%2065.8101C278.346%2065.336%20277.96%2064.8782%20277.563%2064.4366M360.236%20377.756C351.502%20393.715%20347.15%20412.011%20345.031%20427.753C342.57%20446.036%20324.681%20460.318%20306.903%20455.387C281.572%20448.408%20252.243%20437.522%20225.853%20435.493C222.374%20435.226%20185.407%20432.423%20185.407%20432.423C178.868%20431.957%20172.73%20429.099%20168.163%20424.396L98.4698%20352.623C90.8534%20344.78%2088.7918%20333.084%2093.2672%20323.109C93.2672%20323.109%20136.362%20228.393%20137.962%20223.467C138.122%20222.975%20138.325%20222.104%20138.563%20220.91M277.563%2064.4366C267.794%2053.5856%20250.924%2052.5615%20239.902%2062.4764L157.458%20136.645C152.859%20140.781%20149.84%20146.388%20148.917%20152.504C145.784%20173.277%20140.712%20210.156%20138.563%20220.91%20306.903%20455.387C281.572%20448.408%20252.243%20437.522%20225.853%20435.493C222.374%20435.226%20185.407%20432.423%20185.407%20432.423C178.868%20431.957%20172.73%20429.099%20168.163%20424.396L98.4698%20352.623C90.8534%20344.78%2088.7918%20333.084%2093.2672%20323.109C93.2672%20323.109%20136.362%20228.393%20137.962%20223.467C138.122%20222.975%20138.325%20222.104%20138.563%20220.91%22%20stroke%3D%22currentColor%22%20stroke-width%3D%2240%22%2F%3E%3C%2Fsvg%3E");
  -webkit-mask-image: var(--icon-settings-svg);
  mask-image: var(--icon-settings-svg);
  -webkit-mask-position: 50% 50%;
  mask-position: 50% 50%;
  -webkit-mask-size: 100%;
  mask-size: 100%;
  -webkit-mask-repeat: no-repeat;
