  height: 24px;
  background-color: var(--text-normal);
}

html body.obsidian-app div.workspace-drawer-header-icon.mod-settings {
  border: var(--border-width) solid var(--aubade-divider-color);
  background-image: none;
  background-color: var(--background-secondary);
  box-shadow: var(--button-shadow-offset) var(--button-shadow-offset) 0 0 var(--aubade-divider-color);
  opacity: 1;
  transition: var(--button-transition);
}

@media (hover: hover) {
  html body.obsidian-app div.workspace-drawer-header-icon.mod-settings:hover {
    transform: translate(var(--button-lift), var(--button-lift));
    box-shadow: var(--button-shadow-hover-offset) var(--button-shadow-hover-offset) 0 0 var(--aubade-divider-color);
  }
}

html body.obsidian-app .workspace-drawer-header-icon.mod-settings:active {
  transform: translate(var(--button-press), var(--button-press));
  box-shadow: none;
}

html body.obsidian-app .workspace-drawer-vault-actions .clickable-icon {
  border: var(--border-width) solid var(--aubade-divider-color);
  background-color: var(--background-secondary);
  box-shadow: var(--button-shadow-offset) var(--button-shadow-offset) 0 0 var(--aubade-shadow-color);
  transition: var(--button-transition);
  transform: translate(0, 0);
}

@media (hover: hover) {
  html body.obsidian-app .workspace-drawer-vault-actions .clickable-icon:hover {
    transform: translate(var(--button-lift), var(--button-lift));
    box-shadow: var(--button-shadow-hover-offset) var(--button-shadow-hover-offset) 0 0 var(--aubade-shadow-color);
  }
}

html body.obsidian-app .workspace-drawer-vault-actions .clickable-icon:active {
  transform: translate(var(--button-press), var(--button-press));
  box-shadow: none;
}

/* Mobile exception: keep the "button" shadow, but don't depress on press */
html body.obsidian-app.is-mobile .workspace-drawer-vault-actions .clickable-icon:active {
  transform: translate(0, 0);
  box-shadow: var(--button-shadow-offset) var(--button-shadow-offset) 0 0 var(--aubade-shadow-color);
}

/* ================================================================= */
/* 11. MODAL BUTTONS                                                 */
/* ----------------------------------------------------------------- */
/* Button physics inside modals. Base button styling lives in 28.    */
/* See also: 28 (global button frame), 21                            */
/* ================================================================= */

/* -- Base styles -------------------------------------------------- */
html body.obsidian-app .modal button:not(.mod-cta):not(.mod-warning):not(.mod-destructive) {
  background-color: var(--interactive-normal);
  color: var(--text-normal);
  transition: var(--button-transition);
}

/* -- Shadows & transforms ----------------------------------------- */
html body.obsidian-app .modal button {
  box-shadow: var(--button-shadow-offset) var(--button-shadow-offset) 0 0 var(--aubade-shadow-color);
  border-radius: 0;
}

html body.obsidian-app .modal button:hover {
  transform: translate(var(--button-lift), var(--button-lift));
  box-shadow: var(--button-shadow-hover-offset) var(--button-shadow-hover-offset) 0 0 var(--aubade-shadow-color);
}

html body.obsidian-app .modal button:active {
  transform: translate(var(--button-press), var(--button-press));
  box-shadow: none;
}

/* -- CTA buttons -------------------------------------------------- */
html body.obsidian-app .modal button.mod-cta {
  background-color: var(--background-primary);
  color: var(--text-normal);
  transition: var(--button-transition);
}

html body.obsidian-app .setting-item-control button.mod-cta:active {
  transform: translate(var(--button-press), var(--button-press));
  box-shadow: none;
}

@media (hover: hover) {
  html body.obsidian-app .modal button.mod-cta:hover {
    background-color: var(--interactive-accent-hover);
    color: var(--aubade-on-accent-hover);
