/* -- UI font ------------------------------------------------------ */
html body.obsidian-app .metadata-container,
html body.obsidian-app .inline-title,
html body.obsidian-app .view-header-title,
html body.obsidian-app .cm-header,
html body.obsidian-app .status-bar,
html body.obsidian-app .workspace-ribbon,
html body.obsidian-app .modal,
html body.obsidian-app .menu,
html body.obsidian-app .nav-file-tag,
html body.obsidian-app .tag-pane-tag-count,
html body.obsidian-app .tree-item-flair,
html body.obsidian-app .tree-item-inner:not(.nav-file-title-content):not(.nav-folder-title-content),
html body.obsidian-app h1,
html body.obsidian-app h2,
html body.obsidian-app h3,
html body.obsidian-app h4,
html body.obsidian-app h5,
