html body.obsidian-app.is-mobile.theme-light .view-header-nav-buttons::after,
html body.obsidian-app.is-mobile.theme-light .mobile-navbar.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .mobile-navbar.mod-raised::after,
html body.obsidian-app.is-mobile.theme-light .sidebar-toggle-button.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .sidebar-toggle-button.mod-raised::after,
html body.obsidian-app.is-mobile.theme-light .workspace-drawer-header-icon.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .workspace-drawer-header-icon.mod-raised::after,
html body.obsidian-app.is-mobile.theme-light .modal-close-button.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .modal-close-button.mod-raised::after,
html body.obsidian-app.is-mobile.theme-light .modal-header-button.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .modal-header-button.mod-raised::after,
html body.obsidian-app.is-mobile.theme-light .modal-setting-back-button.mod-raised::before,
html body.obsidian-app.is-mobile.theme-light .modal-setting-back-button.mod-raised::after {
  display: none;
}

html body.obsidian-app.is-mobile .view-action,
html body.obsidian-app.is-mobile .view-actions .clickable-icon,
html body.obsidian-app.is-mobile .view-header-nav-buttons .clickable-icon {
