  transform: translate(var(--button-press), var(--button-press));
  box-shadow: none;
}

html body.obsidian-app.is-mobile .mobile-navbar-action,
html body.obsidian-app.is-mobile .mobile-navbar-action:active,
html body.obsidian-app.is-mobile .mobile-navbar-action.is-active,
html body.obsidian-app.is-mobile .mobile-navbar .clickable-icon,
html body.obsidian-app.is-mobile .mobile-navbar .clickable-icon:active {
