}

html body.obsidian-app.is-mobile .workspace-drawer-tab-options-list .workspace-tab-header.is-active :is(.workspace-tab-header-inner-icon svg, .workspace-tab-header-inner-title) {
  color: var(--text-muted);
  stroke: var(--text-muted);
