}

html body.obsidian-app .community-item {
  border-radius: 0;
}

html body.obsidian-app.theme-light .canvas-wrapper path.canvas-display-path {
  stroke: var(--aubade-divider-color);
  fill: none;
  stroke-opacity: 1;
  opacity: 1;
}

html body.obsidian-app.theme-light .canvas-wrapper polygon,
html body.obsidian-app.theme-light .canvas-wrapper polyline {
