html body.obsidian-app.theme-dark .menu-item.mod-checked.selected .menu-item-title,
html body.obsidian-app.theme-dark .menu-item.mod-checked:hover .menu-item-title,
html body.obsidian-app.theme-dark .menu-item.mod-checked.selected .menu-item-icon,
html body.obsidian-app.theme-dark .menu-item.mod-checked:hover .menu-item-icon {
  color: var(--text-normal);
}

/* CREATE CAPTIONS UNDER IMAGES EMBEDDED IN NOTES */


/* -- Image captions ----------------------------------------------- */
/* Column flex so the image and its caption share a centre line: the caption is
   centred on the image rather than on the text column, whichever is wider. */
html body.obsidian-app .markdown-rendered .image-embed[alt] {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  max-width: 100%;
}

/* Extracts and displays the alt attribute as a caption block */
html body.obsidian-app .markdown-rendered .image-embed[alt]::after {
  content: attr(alt);
  display: block;
  text-align: center;
  font-size: 0.85em;
  color: var(--text-muted);
  margin-top: 0.5rem;
  font-family: var(--font-interface-override);
}

/* Obsidian fills alt with the file name for ![[embeds]] that carry no caption,
   which would print the file name under every uncaptioned image. Caption only
   what the author actually wrote. */
html body.obsidian-app .markdown-rendered .image-embed[alt=""]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".png" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".jpg" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".jpeg" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".gif" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".webp" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".svg" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".avif" i]::after,
html body.obsidian-app .markdown-rendered .image-embed[alt$=".bmp" i]::after {
  content: none;
  display: none;
}

/* ================================================================= */
/* 30. TIMELINE CSSCLASS - DESKTOP                                   */
/* ----------------------------------------------------------------- */
/* Opt-in three-item timeline layout for the custom-timeline cssclas */
/* See also: 31                                                      */
/* ================================================================= */

/* -- Grid layout & dashed spine ----------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul) {
  display: grid;
  grid-template-columns: var(--tl-date-width) 1fr;
  column-gap: 0;
  list-style: none;
  padding: 2rem 1rem;
  margin: 0;
  position: relative;
  background-image: repeating-linear-gradient(to bottom,
      var(--text-muted) 0px,
      var(--text-muted) 6px,
      transparent 6px,
      transparent 12px);
  background-size: 4px 100%;
  background-position: calc(1rem + var(--tl-date-width) - 2px) 0;
  background-repeat: repeat-y;
}

/* -- List item resets --------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li>.list-bullet {
  display: none;
}

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li {
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
  align-self: start;
  transition: background-color 0.4s ease;
}

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li>p {
  margin: 0;
  padding: 0;
}

/* -- Date item (3n+1) --------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1) {
  grid-column: 1;
  grid-row: span 2;
  align-self: start;
  text-align: right;
  padding-right: 2rem;
  padding-top: 0.15rem;
  padding-bottom: var(--tl-row-gap);
  font-size: 1.4rem;
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.3;
  word-break: break-word;
  overflow-wrap: break-word;
  color: var(--color-accent, var(--text-accent));
  font-family: var(--font-interface);
  transition: color 0.3s ease, letter-spacing 0.3s ease;
}

/* -- Dot marker --------------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1)::before {
  content: "";
  display: block;
  position: absolute;
  right: 0px;
  top: 8px;
  height: var(--tl-dot-size);
  width: var(--tl-dot-size);
  background-color: var(--tl-dot-color);
  border-radius: 50%;
  transform: translateX(50%);
  z-index: 2;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
}

/* -- ::after reserved --------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1)::after {
  display: none;
}

/* -- Title item (3n+2) -------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+2) {
  grid-column: 2;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-normal);
  font-family: var(--font-interface);
  padding: 0.15rem 0 0.15rem 2.5rem;
}

/* -- Content item (3n) -------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n) {
  grid-column: 2;
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.8;
  padding: 0 0 var(--tl-row-gap) 2.5rem;
}

/* -- Max width ---------------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline .markdown-preview-sizer {
  max-width: 800px;
  width: 100%;
  margin-left: auto;
  margin-right: auto;
}

/* -- Hover: row highlight ----------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover,
html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover+li,
html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover+li+li {
  background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
  border-radius: 0;
}

/* -- Hover: dot scale --------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover::before {
  transform: translateX(50%) scale(1.4);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--tl-dot-color) 30%, transparent);
  transition: all 0.2s ease;
}

/* -- Entrance animation ------------------------------------------- */

html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+2),
html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n) {
  animation: slide-in 0.5s cubic-bezier(0.4, 0, 0.2, 1) both;
}

/* -- Keyframes ---------------------------------------------------- */

@keyframes slide-in {
  from {
    opacity: 0;
    transform: translateX(20px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ================================================================= */
/* 31. TIMELINE CSSCLASS - MOBILE                                    */
/* ----------------------------------------------------------------- */
/* Single-column timeline below 480px.                               */
/* See also: 30                                                      */
/* ================================================================= */

@media (max-width: 480px) {

  html body.obsidian-app .markdown-preview-view.custom-timeline {
    --tl-row-gap: 2rem;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul) {
    grid-template-columns: 1fr;
    padding: 1rem 1rem 1rem 2rem;
    background-position: 8px 0;
    background-size: 4px 12px;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1) {
    grid-column: 1;
    grid-row: auto;
    text-align: left;
    padding: 0.15rem 0 0.1rem 1.5rem;
    font-size: 1rem;
    font-weight: 900;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1)::before {
    right: auto;
    left: -2px;
    top: 8px;
    height: var(--tl-dot-size);
    width: var(--tl-dot-size);
    transform: translateX(-50%);
    animation: none;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover::before {
    transform: translateX(-50%) scale(1);
    box-shadow: none;
    transition: none;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover,
  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover+li,
  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+1):hover+li+li {
    background-color: transparent;
    transition: none;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n+2) {
    grid-column: 1;
    padding: 0 0 0.15rem 2rem;
    font-size: 1rem;
    animation: none;
  }

  html body.obsidian-app .markdown-preview-view.custom-timeline ul:not(ul ul)>li:nth-child(3n) {
    grid-column: 1;
    padding: 0 0 var(--tl-row-gap) 2rem;
    font-size: 0.85rem;
    animation: none;
  }
}

